            rugged += 0.7 * np.sin(18 * x[i]) * np.cos(9 * x[i]) + 0.3 * np.sin(25 * x[i])**2 + 0.15 * np.cos(30 * x[i])

        # Asymmetric basin term with increased complexity and different scaling per dimension
        basin = 0.0
        for i in range(self.dim):
            basin += 0.5 * (x[i] - 2.8)**6 + 0.3 * (x[i] + 2.0)**5 + 0.15 * np.sin(15 * x[i]) * np.cos(7 * x[i])

        # Additional noise term with increased amplitude and frequency to increase landscape complexity
        noise = 0.15 * np.sum(np.sin(12 * x) * np.cos(6 * x))

        # Cross-dimensional interaction enhancement with non-linear coupling terms - slightly modified
        cross_interaction = 0.0
        for i in range(self.dim):
            for j in range(i+1, self.dim):
                cross_interaction += np.sin(x[i] * x[j]) * np.exp(-0.07 * (x[i]**2 + x[j]**2)) + 0.35 * np.cos(4 * x[i] + 3 * x[j])  # Slight change in coefficient

        # Additional higher-order polynomial coupling
        high_order = 0.0
        for i in range(self.dim):
            for j in range(i+1, self.dim):
                for k in range(j+1, self.dim):
                    high_order += 0.25 * (x[i] * x[j] * x[k])**3  # Slight change in coefficient

        # Additional chaotic cosine component with varying frequency
        chaotic_cos = 0.0
        for i in range(self.dim):
            freq = 5**(i % 6 + 1)
            amp = 1.5 + 0.7 * np.cos(i * 0.8)
            chaotic_cos += amp * np.cos(freq * x[i]) * np.exp(-0.2 * x[i]**2)

        return quadratic + chaotic + exp_decay + modulation + coupling + rugged + basin + noise + cross_interaction + high_order + chaotic_cos
